mutation FlxDonationCartAdd($input: FlxDonationCartAddInput!) {
  flxDonationCartAdd(input: $input) {
    itemKey
    cart {
      items {
        key
        kind
        flxDonation {
          option
          units
          names
          amount
        }
      }
    }
    errors {
      code
      message
      field
    }
  }
}

